// Get scheduled posts from content calendar
// In production, this would query Google Sheets, Notion, Airtable, etc.

const now = new Date();

// Example scheduled posts structure
const scheduledPosts = [
  /*
  {
    id: 'post_001',
    title: 'New Product Launch',
    content: 'Excited to announce our new product...',
    platforms: ['LinkedIn', 'Twitter/X', 'Facebook'],
    postType: 'Image Post',
    mediaUrl: 'https://example.com/product.jpg',
    linkUrl: 'https://example.com/product',
    hashtags: '#newproduct #launch #innovation',
    scheduledTime: '2026-01-07T09:00:00Z',
    campaign: 'Product Launch',
    status: 'scheduled',
    aiOptimization: 'Optimize for each platform'
  }
  */
];

return { json: { posts: scheduledPosts, checkedAt: now.toISOString() } };

// Filter posts that are due for publishing
const data = $input.first().json;
const posts = data.posts || [];
const now = new Date();

// Filter posts that should be published now (within 5 minute window)
const duePosts = posts.filter(post => {
  if (post.status !== 'scheduled') return false;
  const scheduledTime = new Date(post.scheduledTime);
  const diffMinutes = (scheduledTime - now) / (1000 * 60);
  return diffMinutes <= 5 && diffMinutes >= -5;
});

if (duePosts.length === 0) {
  return { json: { hasPosts: false, message: 'No posts due for publishing' } };
}

return duePosts.map(post => ({ json: { ...post, hasPosts: true } }));

// Parse and normalize post request
const input = $input.first().json;

const post = {
  id: `post_${Date.now()}`,
  title: input['Post Title/Reference'] || input.title || 'Untitled Post',
  content: input['Post Content'] || input.content || '',
  platforms: input['Target Platforms'] || input.platforms || ['LinkedIn'],
  postType: input['Post Type'] || input.postType || 'Text Only',
  mediaUrl: input['Image/Media URL'] || input.mediaUrl || '',
  linkUrl: input['Link URL (for link shares)'] || input.linkUrl || '',
  hashtags: input['Hashtags'] || input.hashtags || '',
  scheduleType: input['Schedule Type'] || 'Publish Now',
  scheduledTime: input['Scheduled Date/Time'] || input.scheduledTime || new Date().toISOString(),
  campaign: input['Campaign/Category'] || input.campaign || 'Other',
  aiOptimization: input['AI Optimization'] || 'Use content as-is',
  createdAt: new Date().toISOString(),
  status: 'pending'
};

// Parse platforms if string
if (typeof post.platforms === 'string') {
  post.platforms = post.platforms.split(',').map(p => p.trim());
}

// Determine if immediate publish or schedule
post.publishNow = post.scheduleType === 'Publish Now';

return { json: post };

