// Parse AI optimized content and prepare for each platform
const data = $input.first().json;

// Parse AI response
let optimizedContent = {};
try {
  const aiOutput = data.output || data.text || '';
  const jsonMatch = aiOutput.match(/```json\n?([\s\S]*?)\n?```/) || aiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    optimizedContent = JSON.parse(jsonMatch[1] || jsonMatch[0]);
  }
} catch (e) {
  // Use original content if parsing fails
  optimizedContent = {
    linkedin: { content: data.content, hashtags: data.hashtags },
    twitter: { content: data.content.substring(0, 280), hashtags: data.hashtags },
    facebook: { content: data.content, hashtags: data.hashtags },
    instagram: { content: data.content, hashtags: data.hashtags }
  };
}

// Create platform-specific posts
const platforms = data.platforms || [];
const platformPosts = [];

if (platforms.includes('LinkedIn')) {
  platformPosts.push({
    ...data,
    platform: 'LinkedIn',
    platformContent: optimizedContent.linkedin?.content || data.content,
    platformHashtags: optimizedContent.linkedin?.hashtags || data.hashtags
  });
}

if (platforms.includes('Twitter/X')) {
  platformPosts.push({
    ...data,
    platform: 'Twitter/X',
    platformContent: optimizedContent.twitter?.content || data.content.substring(0, 280),
    platformHashtags: optimizedContent.twitter?.hashtags || data.hashtags
  });
}

if (platforms.includes('Facebook')) {
  platformPosts.push({
    ...data,
    platform: 'Facebook',
    platformContent: optimizedContent.facebook?.content || data.content,
    platformHashtags: optimizedContent.facebook?.hashtags || ''
  });
}

if (platforms.includes('Instagram')) {
  platformPosts.push({
    ...data,
    platform: 'Instagram',
    platformContent: optimizedContent.instagram?.content || data.content,
    platformHashtags: optimizedContent.instagram?.hashtags || data.hashtags
  });
}

return platformPosts.map(p => ({ json: p }));

// Post to LinkedIn
const post = $input.first().json;

if (post.platform !== 'LinkedIn') {
  return { json: { ...post, skipped: true, reason: 'Not LinkedIn platform' } };
}

// In production, this would use LinkedIn API
const linkedInPost = {
  author: 'urn:li:organization:YOUR_ORG_ID',
  lifecycleState: 'PUBLISHED',
  specificContent: {
    'com.linkedin.ugc.ShareContent': {
      shareCommentary: {
        text: `${post.platformContent}\n\n${post.platformHashtags}`
      },
      shareMediaCategory: post.mediaUrl ? 'IMAGE' : 'NONE',
      media: post.mediaUrl ? [{
        status: 'READY',
        originalUrl: post.mediaUrl
      }] : []
    }
  },
  visibility: {
    'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC'
  }
};

return {
  json: {
    ...post,
    linkedInPost,
    posted: true,
    postedAt: new Date().toISOString(),
    postUrl: 'https://linkedin.com/feed/update/urn:li:share:PLACEHOLDER'
  }
};

// Post to Twitter/X
const post = $input.first().json;

if (post.platform !== 'Twitter/X') {
  return { json: { ...post, skipped: true, reason: 'Not Twitter platform' } };
}

// Ensure tweet is within character limit
let tweetText = post.platformContent;
const hashtagsLength = post.platformHashtags?.length || 0;

if (tweetText.length + hashtagsLength + 2 > 280) {
  tweetText = tweetText.substring(0, 280 - hashtagsLength - 5) + '...';
}

const fullTweet = `${tweetText}\n${post.platformHashtags}`.trim();

// In production, this would use Twitter API v2
const twitterPost = {
  text: fullTweet,
  media: post.mediaUrl ? { media_ids: ['PLACEHOLDER_MEDIA_ID'] } : undefined
};

return {
  json: {
    ...post,
    twitterPost,
    finalTweet: fullTweet,
    characterCount: fullTweet.length,
    posted: true,
    postedAt: new Date().toISOString(),
    postUrl: 'https://twitter.com/user/status/PLACEHOLDER'
  }
};

// Post to Facebook
const post = $input.first().json;

if (post.platform !== 'Facebook') {
  return { json: { ...post, skipped: true, reason: 'Not Facebook platform' } };
}

// In production, this would use Facebook Graph API
const facebookPost = {
  message: `${post.platformContent}\n\n${post.platformHashtags}`.trim(),
  link: post.linkUrl || undefined,
  attached_media: post.mediaUrl ? [{ media_fbid: 'PLACEHOLDER' }] : undefined
};

return {
  json: {
    ...post,
    facebookPost,
    posted: true,
    postedAt: new Date().toISOString(),
    postUrl: 'https://facebook.com/page/posts/PLACEHOLDER'
  }
};

// Post to Instagram
const post = $input.first().json;

if (post.platform !== 'Instagram') {
  return { json: { ...post, skipped: true, reason: 'Not Instagram platform' } };
}

// Instagram requires an image or video
if (!post.mediaUrl && post.postType !== 'Text Only') {
  return {
    json: {
      ...post,
      posted: false,
      error: 'Instagram requires media (image or video)'
    }
  };
}

// In production, this would use Instagram Graph API
const instagramPost = {
  caption: `${post.platformContent}\n\n${post.platformHashtags}`.trim(),
  image_url: post.mediaUrl,
  media_type: post.postType === 'Video Post' ? 'VIDEO' : 'IMAGE'
};

return {
  json: {
    ...post,
    instagramPost,
    posted: true,
    postedAt: new Date().toISOString(),
    postUrl: 'https://instagram.com/p/PLACEHOLDER'
  }
};

// Update calendar status
const post = $input.first().json;

// In production, this would update the content calendar
return {
  json: {
    ...post,
    calendarUpdated: true,
    newStatus: post.posted ? 'published' : 'failed'
  }
};
